INSERT INTO pages (id, user_id, title, icon, parent_id, sort_order, content, is_favorite, created_at, updated_at)
VALUES ('dy_e121558d7a4e', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Getting started with Dynalist', '📝', 'dy_134262ba4ebf', 0, '<ul><li>Hi there, thanks for using Dynalist! 👋</li><li>This document contains the essentials to get you started. Keep it as a reference, and you can also add your own notes on how to use Dynalist.</li><li>☐ The Essentials List<p style="margin:4px 0 6px;color:var(--muted,#6b7280);font-size:0.95em;">Check things off after you have tried them</p><ul><li>Dynalist is all about nested lists<ul><li><code>Tab</code> to go a level deeper 👉</li><li>And <code>Shift+Tab</code> to come back 👈</li></ul></li><li>If you put your mouse on a list item, a hamburger menu icon and a 🔍 icon will show up<ul><li>Click on the 🔍 to &quot;zoom in&quot; on that item</li><li>Click on the menu for a number of other options (this menu is called the item menu)</li></ul></li><li>Convert lists to checklists by choosing &quot;Add checkbox to children&quot; in the item menu or <code>Ctrl+Shift+C</code></li><li>You can sort list items by dragging their bullet points (works for multiple items too!)</li><li>You can select multiple items as well! Simply drag the mouse to select</li><li>Create a new document by clicking on the &quot;+&quot; icon in the header of the left sidebar</li><li>Right click on a document for a list of things you can do with it</li><li>Add a note to an item by pressing <code>Shift+Enter</code><p style="margin:4px 0 6px;color:var(--muted,#6b7280);font-size:0.95em;">You can go back to the item using the same shortcut</p></li><li>Use the <code>!</code> trigger to open the date picker and add dates<p style="margin:4px 0 6px;color:var(--muted,#6b7280);font-size:0.95em;">Make sure to type it after a space</p></li><li>(Optional) If you previously use WorkFlowy, you can import from WorkFlowy by choosing the option in the main menu in the top right corner</li></ul></li><li>☐ The Max Efficiency List<p style="margin:4px 0 6px;color:var(--muted,#6b7280);font-size:0.95em;">Check things off after you have tried them!</p><ul><li>Use #tags to group things</li><li>Use <code>Ctrl/Cmd+O</code> to quickly jump between documents</li><li>Bookmark a place by clicking on the star, you can go back to it later very quickly in the bookmark pane<p style="margin:4px 0 6px;color:var(--muted,#6b7280);font-size:0.95em;">Access the bookmark with the shortcut <code>Ctrl/Cmd+Shift+B</code></p></li><li>To insert a link to another item, type <code>[[</code> and start searching for items to add</li><li>There are keyboard shortcuts for almost everything, use <code>Ctrl/Cmd+?</code> to bring up the cheatsheet!</li></ul></li><li>Need help?<ul><li>Search for an answer over at <a href="https://help.dynalist.io/" target="_blank" rel="noopener noreferrer">our help center</a></li><li>In the main menu (the one on the top right of this page), choose Help 🡒 Contact us, we''ll reply asap</li></ul></li></ul>', false, now(), now())
ON CONFLICT (user_id, id) DO UPDATE SET
