INSERT INTO pages (id, user_id, title, icon, parent_id, sort_order, content, is_favorite, created_at, updated_at)
VALUES ('dy_9f4959a2e72a', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Clase de Inglés - 4 de Septiembre', '📝', 'dy_9d1a500ade9f', 0, '<h2><strong>Main Aims (Objetivos)</strong></h2>
<ul><li>Aprender vocabulario sobre <em>career paths</em> (trayectorias profesionales) y <em>company structure</em> (estructura empresarial).</li><li>Reading comprehension y Speaking fluency.</li></ul>
<h2><strong>Vocabulary: Company Structure</strong> #vocabulary #business</h2>
<ul><li><strong>Career ladder</strong>: Escala corporativa.<ul><li><em>Go up the career ladder</em> / <em>Get a promotion</em>: Ascender / Conseguir un ascenso.</li><li><em>Demotion</em>: Bajar de posición / Democión.</li></ul></li><li><strong>Restructure / Downsize / Delayer</strong>: Reestructurar o reducir el tamaño de la empresa para recortar gastos.</li><li><strong>Flatter vs. Leaner</strong>:<ul><li><em>Flatter</em>: Reducir los niveles de gerencia (<em>management levels</em>) en la jerarquía.</li><li><em>Leaner</em>: Tener menos empleados, pero más productivos.</li></ul></li><li><strong>In-house vs. Outsource</strong>:<ul><li><em>In-house</em>: Personal o equipo interno.</li><li><em>Outsource</em>: Subcontratar tareas a otras empresas (suele ser más barato).</li></ul></li><li><strong>Freelance / Temporary contract</strong>: Trabajador independiente o contrato temporal.<ul><li>Genera flexibilidad, pero también <em>job insecurity</em> (inseguridad laboral).</li></ul></li></ul>
<h2><strong>Vocabulary: Leaving a Company</strong> #vocabulary #business</h2>
<ul><li><strong>Resign / Hand in your notice</strong>: Renunciar voluntariamente (porque quieres dejar la compañía).</li><li><strong>Dismissed / Fired / Sacked</strong>: Ser despedido por cometer algún error o falta.</li><li><strong>Made redundant / Laid off</strong>: Ser despedido porque la empresa ya no te necesita (recortes de personal), no por hacer algo mal.</li><li><strong>Retirement / Retire</strong>: Jubilación (sustantivo) / Jubilarse (verbo).</li></ul>
<h2><strong>Expressions &amp; Pronunciation</strong> #expressions #pronunciation</h2>
<ul><li><strong>Is it worth it?</strong>: ¿Vale la pena? (conveniente o bueno por sus beneficios).</li><li><strong>Since I started</strong>: Desde que empecé.</li><li><strong>Rate</strong>: Calificar qué tan bueno es algo (ej. estrellas de Google Maps).</li><li><strong>Regla de pronunciación</strong>:<ul><li>Diferencia entre palabras CVC (Consonante-Vocal-Consonante): <em>ladder</em>, <em>run</em>, <em>cut</em>.</li><li>Y palabras con estructura &quot;vocal_e&quot;: <em>lade</em>, <em>rune</em>, <em>cute</em>.</li></ul></li></ul>
<h2><strong>Homework (Writing)</strong> #homework</h2>
<ul><li>What do you prefer at a job? A career ladder or changing companies?</li><li>How do you feel about freelance work?</li><li>How important is job security?</li></ul>
<ul><li><strong>Tip para Dynalist:</strong> Si quieres que la traducción o explicación quede como una &quot;nota&quot; debajo del concepto principal en lugar de un sub-punto, puedes usar Shift + Enter en Dynalist después de pegar el texto.</li></ul>', false, now(), now())
