VALUES ('dy_155fbc6ae507', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Búsqueda de producto', '📁', 'dy_a2ea2c5dc8a2', 0, '<p>Carpeta importada desde Dynalist: <strong>Búsqueda de producto</strong></p>', false, now(), now())
