INSERT INTO pages (id, user_id, title, icon, parent_id, sort_order, content, is_favorite, created_at, updated_at)
VALUES ('dy_60cbafbd612a', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, '🚀El Prompt Optimizado búsqueda de producto', '📝', 'dy_155fbc6ae507', 0, '<ul><li>Actúa como un experto de élite en investigación de productos (Product Research) y cazador de oportunidades para Amazon FBA. Tu objetivo es realizar una lluvia de ideas (brainstorming) de 50 productos viables. Configuración del mercado objetivo (Modificado por el usuario): - Mercado de Amazon: https://www.[DOMINIO_AMAZON] - Divisa local: [DIVISA] - Rango de precios: Entre [PRECIO_MIN] y [PRECIO_MAX] [DIVISA] https://www.programalanzamiento.com/ REGLA DE ADAPTACIÓN SEGÚN EL TAMAÑO DEL MERCADO (CRÍTICO): Analiza el dominio de Amazon que se ha configurado arriba y aplica estrictamente esta lógica: - SI EL MERCADO ES USA (amazon.com): El volumen es gigantesco. Necesito que busques subnichos EXTREMADAMENTE RAROS, extraños, ultra-específicos y muy poco evidentes. En este mercado, la rareza extrema sigue teniendo suficiente volumen de facturación. - SI EL MERCADO ES MÁS PEQUEÑO (amazon.es, amazon.com.mx, u otros europeos/latinos): El volumen es menor. NO busques rarezas extremas ni productos extravagantes porque no tendrán ventas. En su lugar, busca productos de &quot;PERFIL BAJO&quot; o &quot;SEMI-OCULTOS&quot;. Deben ser productos útiles, nichos discretos, específicos y no masivos, pero que resuelvan una necesidad clara y tengan una demanda local saludable y comprobada. Evita commodities ultra-competidos (no fundas de móvil, no rodillos de jade, no mochilas genéricas), pero mantente dentro de productos lógicos con rotación. Aplica estos filtros visualizando el mercado seleccionado: 1. Facturación del líder: El vendedor principal de ese subnicho no debe superar el equivalente a 25.000 USD/mes en la divisa local (ajusta mentalmente según el tamaño del mercado). 2. Fragmentación: Al menos 3 vendedores diferentes generando ventas estables en la primera página. 3. Barrera de entrada baja: En el Top 10 debe haber al menos un competidor con 50 reviews o menos. 4. Temporalidad: El nicho debe venderse durante todo el año (sin picos puramente estacionales). https://www.programalanzamiento.com/ 5. Tracción reciente: Evidencia de listados nuevos que ya estén capturando cuota de mercado. 6. Sin monopolios: Evita nichos dominados por marcas gigantes o Amazon Basics. CRÍTICO - REQUISITO DE FORMATO DE SALIDA: Entrega los 50 resultados EXCLUSIVAMENTE en una tabla renderizada en Markdown nativo. NO utilices bloques de código (```), ni código HTML, ni texto plano. La tabla debe mostrarse visualmente en el chat como si fuera una hoja de Excel, donde las celdas de la última columna sean hipervínculos reales y clicables de inmediato. La tabla debe tener exactamente las siguientes columnas: 1. # (Número del 1 al 50) 2. Keyword (En inglés si es mercado USA; en el idioma local si es España/México, de más de 3 palabras) 3. Traducción/Significado (Al español, si la keyword está en inglés) 4. Tipo de Producto (Breve descripción de qué es) 5. Precio Promedio Estimado (En la divisa configurada) 6. Nivel de Oportunidad (Bajo / Medio / Alto / Muy Alto) 7. Enfoque del Nicho (Indica si es &quot;Rareza Extrema&quot; para USA o &quot;Perfil Bajo/Semi-oculto&quot; para mercado local) 8. Motivo del Nicho (Por qué funciona en este mercado específico, en 1 frase corta) 9. Enlace Directo (Un enlace clicable real con este formato exacto de URL: [Ver en Amazon](https://www.[DOMINIO_AMAZON]/s?k=REMPLAZAR_POR_LA_KEYWORD_U SANDO_SIGNOS_MAS_EN_LOS_ESPACIOS)) https://www.programalanzamiento.com/ Reglas adicionales: No inventes productos que no existan en Amazon, no des ideas genéricas y asegúrate de que los números estimativos tengan coherencia con el mercado seleccionado. Comienza directamente con la tabla.</li><li></li><li></li><li>Por ejemplo: </li><li>Actúa como un experto de élite en investigación de productos (Product Research) y cazador de oportunidades para Amazon FBA. Tu objetivo es realizar una lluvia de ideas (brainstorming) de 50 productos viables. Configuración del mercado objetivo (Modificado por el usuario): - Mercado de Amazon: https://www.amazon.es - Divisa local: EUR - Rango de precios: Entre 35 y 300 EUR https://www.programalanzamiento.com/ REGLA DE ADAPTACIÓN SEGÚN EL TAMAÑO DEL MERCADO (CRÍTICO): Analiza el dominio de Amazon que se ha configurado arriba y aplica estrictamente esta lógica: - SI EL MERCADO ES USA (amazon.com): El volumen es gigantesco. Necesito que busques subnichos EXTREMADAMENTE RAROS, extraños, ultra-específicos y muy poco evidentes. En este mercado, la rareza extrema sigue teniendo suficiente volumen de facturación. - SI EL MERCADO ES MÁS PEQUEÑO (amazon.es, amazon.com.mx, u otros europeos/latinos): El volumen es menor. NO busques rarezas extremas ni productos extravagantes porque no tendrán ventas. En su lugar, busca productos de &quot;PERFIL BAJO&quot; o &quot;SEMI-OCULTOS&quot;. Deben ser productos útiles, nichos discretos, específicos y no masivos, pero que resuelvan una necesidad clara y tengan una demanda local saludable y comprobada. Evita commodities ultra-competidos (no fundas de móvil, no rodillos de jade, no mochilas genéricas), pero mantente dentro de productos lógicos con rotación. Aplica estos filtros visualizando el mercado seleccionado: 1. Facturación del líder: El vendedor principal de ese subnicho no debe superar el equivalente a 25.000 USD/mes en la divisa local (ajusta mentalmente según el tamaño del mercado). 2. Fragmentación: Al menos 3 vendedores diferentes generando ventas estables en la primera página. 3. Barrera de entrada baja: En el Top 10 debe haber al menos un competidor con 50 reviews o menos. 4. Temporalidad: El nicho debe venderse durante todo el año (sin picos puramente estacionales). https://www.programalanzamiento.com/ 5. Tracción reciente: Evidencia de listados nuevos que ya estén capturando cuota de mercado. 6. Sin monopolios: Evita nichos dominados por marcas gigantes o Amazon Basics. CRÍTICO - REQUISITO DE FORMATO DE SALIDA: Entrega los 50 resultados EXCLUSIVAMENTE en una tabla renderizada en Markdown nativo. NO utilices bloques de código (```), ni código HTML, ni texto plano. La tabla debe mostrarse visualmente en el chat como si fuera una hoja de Excel, donde las celdas de la última columna sean hipervínculos reales y clicables de inmediato. La tabla debe tener exactamente las siguientes columnas: 1. # (Número del 1 al 50) 2. Keyword (En inglés si es mercado USA; en el idioma local si es España/México, de más de 3 palabras) 3. Traducción/Significado (Al español, si la keyword está en inglés) 4. Tipo de Producto (Breve descripción de qué es) 5. Precio Promedio Estimado (En la divisa configurada) 6. Nivel de Oportunidad (Bajo / Medio / Alto / Muy Alto) 7. Enfoque del Nicho (Indica si es &quot;Rareza Extrema&quot; para USA o &quot;Perfil Bajo/Semi-oculto&quot; para mercado local) 8. Motivo del Nicho (Por qué funciona en este mercado específico, en 1 frase corta) 9. Enlace Directo (Un enlace clicable real con este formato exacto de URL: [Ver en Amazon](https://www.amazon.es/s?k=REMPLAZAR_POR_LA_KEYWORD_U SANDO_SIGNOS_MAS_EN_LOS_ESPACIOS)) https://www.programalanzamiento.com/ Reglas adicionales: No inventes productos que no existan en Amazon, no des ideas genéricas y asegúrate de que los números estimativos tengan coherencia con el mercado seleccionado. Comienza directamente con la tabla.</li><li></li><li></li></ul>', false, now(), now())
