INSERT INTO pages (id, user_id, title, icon, parent_id, sort_order, content, is_favorite, created_at, updated_at)
VALUES ('dy_2bdc6e499af1', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Teoria', '📝', 'dy_155fbc6ae507', 2, '<ul><li>Reglas de oro<ul><li><strong>1. Precio de venta mínimo</strong>Siempre venderemos productos con un precio de venta superior a 35 euros (o divisa equivalente). El objetivo es tener margen suficiente tras aportar nuestra diferenciación. No importa si el resto del nicho vende barato, siempre que logremos aportar valor para justificar el precio premium. </li><li><strong>2. Límite de facturación del mejor vendedor</strong> El mejor vendedor del nicho no debe superar los límites de facturación establecidos según tu capital disponible. Se debe consultar la tabla del documento adjunto para evitar quedarse corto o largo de presupuesto. Se verifica siempre en el primer paso utilizando la herramienta X-ray de Helium 10.</li><li> <strong>3. Norma opcional (Nivel de reseñas de la competencia)</strong> Buscar que al menos un vendedor en el Top 8 tenga 70 reseñas o menos. No es indispensable si el producto tiene una propuesta de valor y diferenciación reales. Funcionamiento: Estrategia de diferenciación </li></ul></li><li>Fases<ul><li><strong>Fase 1: Inspiración y análisis del mercado</strong> Buscar inspiración fuera de Amazon: Etsy, Pinterest, Google y otras tiendas online. Analizar otros mercados (ej. mirar qué funciona en EE.UU. o Australia si vas a vender en Europa o México). Leer las reseñas negativas de los competidores para descubrir carencias y quejas de los clientes. </li><li><strong>Fase 2: Uso de Inteligencia Artificial</strong>Consejo del profesor: Contrata siempre una suscripción de pago (15-20€/$) de ChatGPT, Gemini o Claude para el proyecto de Amazon. Opcional: Alimentar a la IA con el Excel de &quot;Review Insights&quot; de Helium 10 para que analice reseñas masivamente. Obligatorio: Proporcionar a la IA capturas de pantalla del buscador de Amazon para que analice visualmente a los competidores. Utilizar el prompt de diferenciación en dos pasos (Paso 1: Análisis y propuesta de vías; Paso 2: Diseño del kit y justificación del precio premium). <ul><li>Consejo del profesor: La IA siempre intentará inventarse una diferenciación, pero no siempre tendrá sentido. Usa tu intuición humana para juzgar y guiar sus propuestas. <ul><li>Ejemplos de validación y diferenciación <strong>Cubiletes de dados</strong> Situación del nicho: Océano de homogeneidad, productos básicos compitiendo por precio barato ($13-$29). Estrategia aplicada: Fabricación en cuero de alto calibre (corte por láser que evita moldes caros), forma hexagonal y tapa con cierre magnético. Aumento de valor percibido: Inclusión de dados de metal y <em>packaging</em> de lujo (ideal para producto regalable). Resultado: Producto premium que justifica un precio de $50-$70. <strong>Wall panels display stand (Expositores portátiles)</strong> Situación del nicho: Productos básicos, finos, metálicos y todos iguales. Estrategia aplicada: Iterar con la IA hasta conseguir un diseño con base y baldas de madera, metal más grueso y ruedas de calidad. Resultado: Estética superior para exhibir productos de alta gama, manteniendo la ligereza y portabilidad que exige el cliente. Errores frecuentes en la búsqueda de productos Error frecuente: Elegir sistemas electrónicos, plásticos desde cero o mecanismos de muchas piezas. Requieren creación de moldes que pueden costar entre $3.000 y $8.000. Ejemplo rechazado: Máquina para limpiar gorras o lámpara con control por App inventadas desde cero por la IA. Solución: Si eliges electrónica, usa productos que ya existan en <code>Alibaba</code> y diferéncialos mediante *packaging*, mejores imágenes o carcasas externas. ==Error frecuente==: Aplicar diferenciaciones que carecen de sentido práctico. La IA propone ideas sin lógica humana (ej. sugerir un compartimento secreto en un cubilete de dados). Ejemplo rechazado: Banco para hacer el pino con piezas deslizantes (el cliente necesita máxima estabilidad y fijación, no que se deslice). ==Error frecuente==: Entrar en nichos con demanda insuficiente (muy habitual en mercados pequeños como México o Brasil). Ejemplo rechazado: Vitrina premium iluminada para Lego en Amazon México. Motivo: El mejor vendedor del nicho facturaba solo 3.000 pesos mensuales; la cuota de mercado es demasiado pequeña para rentabilizar el producto. Resumen final ==Experiencia personal==: Estos aprendizajes y errores resumidos en el vídeo me han costado años de experiencia en el sector. ==Consejo del profesor==: Visualiza este vídeo al menos 2 o 3 veces para interiorizar toda la información condensada sin pasar por alto ningún detalle. El éxito requiere echar horas diarias analizando productos, observando el mercado e iterando con la IA hasta encontrar diferenciaciones con sentido real. Ideas clave ==El precio de venta objetivo siempre debe superar los 35€/$==. Nunca superes el límite de facturación del top ventas adaptado a tu capital inicial. Huye de los moldes caros: evita inventar productos de plástico o electrónicos desde cero. La IA es una herramienta de diseño potente, pero la validación final requiere lógica e intuición humana.</li></ul></li></ul></li></ul></li></ul>', false, now(), now())
