INSERT INTO pages (id, user_id, title, icon, parent_id, sort_order, content, is_favorite, created_at, updated_at)
VALUES ('dy_0224ba7be142', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Untitled', '📝', 'dy_0d571f7486b5', 0, '<ul><li>Recibir y auditar los 4 ficheros faltantes de Lynn (CE-RED 2014/53/EU, RoHS, UN 38.3 y MSDS de la pila CR2032)</li><li>Confirmar por escrito con Lynn si la tapa de la pila CR2032 es a prueba de niños y si tiene licencia oficial Apple Find My / MFi</li><li>Pedir a Logan confirmación escrita de cumplimiento REACH (microfibra, tinta digital, neopreno y anilla de aleación de zinc)</li><li>Confirmar por escrito con Logan el desglose exacto de los $3,65/ud (solo collar vs. caja personalizada, manual, kitting y etiquetado FNSKU/CE/GPSR)</li><li>Enviar el Tech Pack Nalupaws v2.1 (eliminando la palabra AirTag) a 4-5 fabricantes nuevos de collares en Alibaba para cotizar 500 uds con montaje</li><li>Contactar con 2-3 fabricantes alternativos del adaptador (Plan B para Lilian Lin)</li><li>Comprar los 2 competidores directos de 22,99 € en Amazon España para comparar calidad y packaging</li><li>Probar el encaje físico de los 3 componentes (localizador Lynn + soporte Lilian Lin + collar Logan): sin holguras, botón protegido y buen volumen del altavoz</li><li>Probar la tensión real de apertura de la hebilla breakaway con peso controlado (2 kg vs. 3 kg)</li><li>Pesar y medir el producto completo ya embalado para pedir cotización exacta de flete a Stocklogistic</li><li>Agendar consulta con MuayTax (código PROGRAMALANZAMIENTO) para salida del Recargo de Equivalencia y alta en los 3 registros EPR (Envases, RAEE y Pilas)</li></ul>', false, now(), now())
