VALUES ('dy_2e6f789a73f1', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Proveedores', '📁', 'dy_a2ea2c5dc8a2', 2, '<p>Carpeta importada desde Dynalist: <strong>Proveedores</strong></p>', false, now(), now())
