INSERT INTO pages (id, user_id, title, icon, parent_id, sort_order, content, is_favorite, created_at, updated_at)
VALUES ('dy_bf93c27fe3e6', '0da167f9-17d4-4d85-bfe1-f878d83ca7e6'::uuid, 'Primer contacto', '📝', 'dy_2e6f789a73f1', 1, '<ul><li>Hello,</li><li>My name is Sergio, and I am the Purchasing Manager at Nalu. We are an established brand that has been developing products for the past 4 years, and we are currently looking for a long-term factory partner to supply tracker accessories for our catalog.</li><li></li><li>We are very interested in your product, but I have a few questions:</li><li>- Could you please confirm the exact weight of the product?</li><li>- What is the expected battery life of this device?</li><li>- Could you please provide a quotation for 300, 500, and 1000 units?</li><li>- Additionally, what is your Minimum Order Quantity (MOQ) for this item?</li><li>Thank you in advance for your time. I look forward to your reply.</li><li>Best regards, Sergio</li><li></li><li></li><li>----------------------------------------------------------------------------------------------------------</li><li>We really like your product, but just have a couple of quick questions:<ul><li>Can you confirm the precise weight (only the tracker)?</li><li>How long does the battery typically last on this device?</li><li>What is its exact thickness?</li></ul></li><li>Thank you in advance for your time. I look forward to your reply.</li><li></li><li>------------------------------------------------</li><li>Hello,</li><li>My name is Sergio, and I am the Purchasing Manager at Nalu. We are an established brand that has been developing products for the past 4 years, and we are currently looking for a long-term factory partner to supply <strong>high-quality</strong> tracker accessories for our catalog.</li><li>Do you have any cat collars or small dog collars?</li><li></li><li></li><li></li><li>Hello,</li><li>My name is Sergio, and I am the Purchasing Manager at Nalu. We are an established brand that has been developing products for the past 4 years, and we are currently looking for a long-term factory partner to supply tracker accessories for our catalog.</li><li>We are very interested in your product, but I have a few questions:</li></ul>', false, now(), now())
